package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Extension;
import org.eclipse.rdf4j.query.algebra.ExtensionElem;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Not;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.QueryModelNormalizerOptimizer;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParser;
import org.junit.jupiter.api.Test;

/**
 * {@link QueryModelNormalizerOptimizer} may push a constant VALUES relation through a scope-changing BIND only when no
 * Filter inside the group can observe that the pushed variable is now bound, i.e. every Filter mentioning a pushed name
 * has that name assured by its own argument.
 */
public class QueryModelNormalizerScopedBindPushTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIXES = "PREFIX : <urn:t:>\n";

	@Test
	public void declinesPushWhenInnerFilterObservesNotBoundOfUnassuredPushedVariable() {
		TupleExpr optimized = normalize("SELECT ?x ?s ?one WHERE { VALUES ?x { :a :b }"
				+ " { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER(!BOUND(?x)) } BIND(1 AS ?one) } }");
		Extension extension = scopedExtension(optimized);
		assertInstanceOf(Filter.class, extension.getArg(), "VALUES must stay outside the scoped BIND\n" + optimized);
		assertInstanceOf(Join.class, extension.getParentNode(), "VALUES must stay joined above the BIND\n" + optimized);
	}

	@Test
	public void declinesPushWhenInnerFilterObservesNotExistsOverUnassuredPushedVariable() {
		TupleExpr optimized = normalize("SELECT ?x ?s WHERE { VALUES ?x { :a :b }"
				+ " { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER NOT EXISTS { ?s :q ?x } } BIND(1 AS ?one) } }");
		Extension extension = scopedExtension(optimized);
		assertInstanceOf(Filter.class, extension.getArg(), "VALUES must stay outside the scoped BIND\n" + optimized);
	}

	/**
	 * The whole group assures ?x through the second pattern, but the Filter sits over the first pattern where ?x is not
	 * assured; bound evaluation would still flip {@code !BOUND(?x)}.
	 */
	@Test
	public void declinesPushWhenNestedFilterOverUnassuredOperandObservesPushedVariable() {
		IRI p = VF.createIRI("urn:t:p");
		IRI q = VF.createIRI("urn:t:q");
		StatementPattern first = new StatementPattern(Var.of("s"), Var.of("_p", p, true, true), Var.of("o"));
		StatementPattern second = new StatementPattern(Var.of("s"), Var.of("_q", q, true, true), Var.of("x"));
		Filter notBound = new Filter(first, new Not(new Bound(Var.of("x"))));
		Extension extension = new Extension(new Join(notBound, second),
				new ExtensionElem(new ValueConstant(VF.createLiteral(1)), "one"));
		extension.setVariableScopeChange(true);
		Join join = new Join(values("x", VF.createIRI("urn:t:a"), VF.createIRI("urn:t:b")), extension);
		QueryRoot root = new QueryRoot(new Projection(join,
				new ProjectionElemList(new ProjectionElem("x"), new ProjectionElem("s"), new ProjectionElem("one"))));

		new QueryModelNormalizerOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		// push must be declined although the group as a whole assures ?x
		assertSame(join, projectionArg(root), "VALUES must stay joined above the scoped BIND\n" + root);
		assertSame(extension, join.getRightArg(), "the scoped BIND must remain the join operand\n" + root);
		Join group = assertInstanceOf(Join.class, extension.getArg(), "the group argument must be untouched\n" + root);
		assertSame(notBound, group.getLeftArg(), root.toString());
		assertSame(second, group.getRightArg(), root.toString());
	}

	@Test
	public void pushesValuesWhenInnerFilterArgumentAssuresThePushedVariable() {
		TupleExpr optimized = normalize("SELECT ?x ?o ?one WHERE { VALUES ?x { :a :b }"
				+ " { GRAPH :g { ?x :p ?o FILTER NOT EXISTS { ?x :q ?z } } BIND(1 AS ?one) } }");
		Extension extension = scopedExtension(optimized);
		Join pushed = assertInstanceOf(Join.class, extension.getArg(),
				"VALUES should be pushed inside the scoped BIND when ?x is assured\n" + optimized);
		assertInstanceOf(BindingSetAssignment.class, pushed.getLeftArg(), optimized.toString());
		assertSame(extension, projectionArg(optimized), "the scoped BIND must now be the projection argument");
	}

	@Test
	public void pushesValuesWhenNoInnerFilterMentionsThePushedVariable() {
		TupleExpr optimized = normalize("SELECT ?x ?o ?one WHERE { VALUES ?x { :a :b }"
				+ " { GRAPH :g { VALUES ?x { UNDEF } ?x :p ?o FILTER(?o != :z) } BIND(1 AS ?one) } }");
		Extension extension = scopedExtension(optimized);
		assertInstanceOf(Join.class, extension.getArg(),
				"a Filter that does not mention ?x cannot observe the push\n" + optimized);
	}

	private static TupleExpr normalize(String query) {
		TupleExpr tupleExpr = new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
		QueryRoot root = new QueryRoot(tupleExpr);
		new QueryModelNormalizerOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		return root;
	}

	private static TupleExpr projectionArg(TupleExpr root) {
		List<Projection> projections = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Projection node) {
				projections.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, projections.size(), root.toString());
		return projections.get(0).getArg();
	}

	private static Extension scopedExtension(TupleExpr root) {
		List<Extension> extensions = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Extension node) {
				if (node.isVariableScopeChange()) {
					extensions.add(node);
				}
				super.meet(node);
			}
		});
		assertEquals(1, extensions.size(), "expected exactly one scoped BIND\n" + root);
		return extensions.get(0);
	}

	private static BindingSetAssignment values(String name, IRI... values) {
		List<BindingSet> rows = new ArrayList<>();
		for (IRI value : values) {
			rows.add(new ListBindingSet(List.of(name), value));
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows);
		return assignment;
	}
}
